text:
#detailsFooter {
  grid-area: footer;
  padding: var(--ab-contact-padding);

  & label {
    margin: 0 4px;
    white-space: nowrap;
  }

  & menulist:not([hidden]) {
    margin-inline: 4px;
    min-block-size: var(--button-height);

    &,
    & .menu-icon {
      -moz-context-properties: fill, stroke;
      fill: color-mix(in srgb, currentColor 20%, transparent);
      stroke: currentColor;
    }
  }
}
